result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/polvm/compile.py", "content": "#!/usr/bin/env python3
"""polvm compiler: policy rules.yaml -> explainable stack-based IR.

Grammar (precedence low..high:  OR < AND < NOT < comparison, parentheses bind tightest):

    expr    := or_expr
    or_expr := and_expr ("or" and_expr)*
    and_expr:= not_expr ("and" not_expr)*
    not_expr:= "not" not_expr | cmp
    cmp     := primary ((">" | "==") primary)?
    primary := NUMBER | STRING | "true" | "false" | IDENT | "(" expr ")"

Opcodes (all instructions are [OPCODE, arg] with arg=None for the operators):

    PUSH_FIELD name   push record field
    PUSH_CONST value  push literal
    GT                pop b, pop a; push (a > b)
    EQ                pop b, pop a; push (a == b)
    AND               pop b, pop a; push bool(a) and bool(b)
    OR                pop b, pop a; push bool(a) or bool(b)
    NOT               pop a;        push not bool(a)

The IR is JSON-serializable so it can be shipped, diffed and audited.
"""

import argparse
import json
import re
import sys

try:
    import yaml
except ImportError as exc:  # pragma: no cover
    raise SystemExit("polvm.compile requires PyYAML (pip install pyyaml)") from exc


class CompileError(ValueError):
    """Raised for tokenizer / parser / validation problems in rule source."""


# --------------------------------------------------------------------------
# Tokenizer
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
      (?P<SPACE>\s+)
    | (?P<NUMBER>\d+(?:\.\d+)?)
    | (?P<STRING>"[^"]*"|'[^']*')
    | (?P<OP>==|>)
    | (?P<LPAREN>\()
    | (?P<RPAREN>\))
    | (?P<IDENT>[A-Za-z_][A-Za-z0-9_]*)
    """,
    re.VERBOSE,
)


def tokenize(src):
    tokens = []
    pos = 0
    while pos < len(src):
        m = _TOKEN_RE.match(src, pos)
        if m is None:
            raise CompileError(f"unexpected character {src[pos]!r} at position {pos}")
        pos = m.end()
        kind = m.lastgroup
        if kind == "SPACE":
            continue
        tokens.append((kind, m.group()))
    return tokens


# --------------------------------------------------------------------------
# Parser -> AST
#
# AST nodes (tuples):
#   ("field", name)
#   ("const", value)
#   ("cmp", op, left, right)      op is ">" or "=="
#   ("and", left, right)
#   ("or",  left, right)
#   ("not", operand)
# --------------------------------------------------------------------------

_CMP_OPS = {">": "GT", "==": "EQ"}
_KEYWORDS = {"and", "or", "not", "true", "false"}


class _Parser:
    def __init__(self, src):
        self.src = src
        self.tokens = tokenize(src)
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def eat(self, kind=None, text=None):
        kind_got, text_got = self.peek()
        if kind is not None and kind_got != kind:
            raise CompileError(
                f"expected {kind} but found {text_got!r} in: {self.src!r}"
            )
        if text is not None and text_got != text:
            raise CompileError(f"expected {text!r} but found {text_got!r} in: {self.src!r}")
        if kind_got is None:
            raise CompileError(f"unexpected end of expression in: {self.src!r}")
        self.i += 1
        return text_got

    def parse(self):
        node = self.or_expr()
        if self.i != len(self.tokens):
            raise CompileError(f"trailing tokens after expression in: {self.src!r}")
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.peek() == ("IDENT", "or"):
            self.eat()
            node = ("or", node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while self.peek() == ("IDENT", "and"):
            self.eat()
            node = ("and", node, self.not_expr())
        return node

    def not_expr(self):
        if self.peek() == ("IDENT", "not"):
            self.eat()
            return ("not", self.not_expr())
        return self.cmp()

    def cmp(self):
        left = self.primary()
        kind, text = self.peek()
        if kind == "OP":
            if text not in _CMP_OPS:
                raise CompileError(f"unsupported comparison operator {text!r}")
            self.eat()
            right = self.primary()
            return ("cmp", text, left, right)
        return left

    def primary(self):
        kind, text = self.peek()
        if kind == "NUMBER":
            self.eat()
            value = float(text) if "." in text else int(text)
            return ("const", value)
        if kind == "STRING":
            self.eat()
            return ("const", text[1:-1])
        if kind == "LPAREN":
            self.eat("(")
            node = self.or_expr()
            self.eat(")")
            return node
        if kind == "IDENT":
            self.eat()
            if text == "true":
                return ("const", True)
            if text == "false":
                return ("const", False)
            if text in _KEYWORDS:
                raise CompileError(f"unexpected keyword {text!r} in: {self.src!r}")
            return ("field", text)
        raise CompileError(
            f"expected a value but found {text!r} in: {self.src!r}"
        )


def parse(src):
    """Parse a `when` expression into an AST."""
    return _Parser(src).parse()


# --------------------------------------------------------------------------
# Compiler: AST -> IR program (list of [opcode, arg])
# --------------------------------------------------------------------------

def compile_ast(node):
    program = []
    kind = node[0]
    if kind == "field":
        program.append(["PUSH_FIELD", node[1]])
    elif kind == "const":
        program.append(["PUSH_CONST", node[1]])
    elif kind == "not":
        program.extend(compile_ast(node[1]))
        program.append(["NOT", None])
    elif kind in ("and", "or"):
        program.extend(compile_ast(node[1]))
        program.extend(compile_ast(node[2]))
        program.append([kind.upper(), None])
    elif kind == "cmp":
        _, op, left, right = node
        program.extend(compile_ast(left))
        program.extend(compile_ast(right))
        program.append([_CMP_OPS[op], None])
    else:  # pragma: no cover
        raise CompileError(f"unknown AST node {kind!r}")
    return program


# --------------------------------------------------------------------------
# Rule-set compilation
# --------------------------------------------------------------------------

def compile_rule(rule):
    try:
        rule_id = rule["id"]
        when_src = rule["when"]
        decision = rule["then"]
    except (KeyError, TypeError) as exc:
        raise CompileError(f"rule is missing required key: {exc}") from exc
    if decision not in ("allow", "deny"):
        raise CompileError(f"rule {rule_id!r}: 'then' must be allow|deny, got {decision!r}")
    ast = parse(when_src)
    return {
        "id": rule_id,
        "when": when_src,
        "then": decision,
        "ast": _ast_to_json(ast),
        "program": compile_ast(ast),
    }


def compile_rules(doc):
    if not isinstance(doc, dict) or not isinstance(doc.get("rules"), list):
        raise CompileError("rules file must be a mapping with a 'rules' list")
    compiled = []
    seen = set()
    for rule in doc["rules"]:
        cr = compile_rule(rule)
        if cr["id"] in seen:
            raise CompileError(f"duplicate rule id {cr['id']!r}")
        seen.add(cr["id"])
        compiled.append(cr)
    return {"version": 1, "rules": compiled}


def load_rules(path):
    with open(path, "r", encoding="utf-8") as fh:
        return yaml.safe_load(fh)


def _ast_to_json(node):
    return list(node)


# --------------------------------------------------------------------------
# Human-readable listings (used by --list and by the tests)
# --------------------------------------------------------------------------

def format_program(program):
    lines = []
    for pc, (op, arg) in enumerate(program):
        if arg is None:
            lines.append(f"{pc:03d} {op}")
        else:
            lines.append(f"{pc:03d} {op} {json.dumps(arg)}")
    return lines


def main(argv=None):
    ap = argparse.ArgumentParser(description="compile policy rules to polvm IR")
    ap.add_argument("rules", help="path to rules.yaml")
    ap.add_argument("-o", "--out", help="write compiled IR here (JSON); default stdout")
    ap.add_argument("--list", action="store_true", help="print per-rule opcode listings")
    args = ap.parse_args(argv)

    doc = load_rules(args.rules)
    ir = compile_rules(doc)
    text = json.dumps(ir, indent=2)

    if args.list:
        for rule in ir["rules"]:
            print(f"# rule {rule['id']}: {rule['when']}  ->  {rule['then']}")
            for line in format_program(rule["program"]):
                print(f"    {line}")
            print()

    if args.out:
        with open(args.out, "w", encoding="utf-8") as fh:
            fh.write(text + "\n")
        print(f"wrote {args.out} ({len(ir['rules'])} rules)", file=sys.stderr)
    else:
        print(text)


if __name__ == "__main__":
    main()
"})
